<script setup lang="ts">
import { motion, useReducedMotion } from 'motion-v';
const reduced = useReducedMotion();
import { loginDestination } from '@/utils/login';
import { ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { useAuth } from '@/stores/auth';
import { errorMessage } from '@/api/client';
const open = ref(false), error = ref(''), busy = ref(false); const router = useRouter(), route = useRoute(); const { user, logout } = useAuth();
const links = [{ label: 'Home', to: '/' }, { label: 'About', to: '/about' }, { label: 'Announcements', to: '/announcements' }, { label: 'Alumni Stories', to: '/stories' }, { label: 'Events', to: '/events' }, { label: 'Gallery', to: '/gallery' }, { label: 'Contact', to: '/contact' }];
watch(() => route.fullPath, () => { open.value = false; });
async function signOut() { busy.value = true; error.value = ''; try { await logout(); await router.push('/'); } catch (e) { error.value = errorMessage(e); } finally { busy.value = false; } }
</script>
<template><header class="sticky top-0 z-50 bg-primary-container shadow-sm"><nav class="mx-auto flex max-w-7xl items-center justify-between gap-4 px-6 py-4" aria-label="Main navigation"><RouterLink to="/" class="shrink-0 text-xl font-bold uppercase tracking-widest text-white">Gray D. Allison HS</RouterLink><div class="hidden items-center gap-5 text-sm font-medium tracking-tight xl:flex"><RouterLink v-for="link in links" :key="link.to" :to="link.to" class="text-slate-200 hover:text-white" exact-active-class="border-b-2 border-white pb-1 text-white">{{ link.label }}</RouterLink></div><div class="hidden items-center gap-4 xl:flex"><RouterLink v-if="!user" to="/login" :class="['rounded-lg px-6 py-2 text-sm', route.path === '/announcements' ? 'bg-white/10 text-white hover:bg-white/20 font-medium' : 'bg-white font-semibold uppercase tracking-wider text-primary-container']">Log in</RouterLink><template v-else><RouterLink v-if="user.profileImage" to="/account/settings"><img :src="user.profileImage" alt="Your profile" referrerpolicy="no-referrer" class="h-9 w-9 rounded-full object-cover"></RouterLink><RouterLink :to="loginDestination(undefined, user.role)" class="text-sm font-semibold text-white">Dashboard</RouterLink><button class="rounded-lg bg-white px-6 py-2 text-sm font-semibold uppercase tracking-wider text-primary-container" :disabled="busy" @click="signOut">Log out</button></template></div><button class="min-h-11 min-w-11 text-sm font-semibold text-white xl:hidden" aria-controls="public-navigation" :aria-expanded="open" @click="open = !open">{{ open ? 'Close menu' : 'Menu' }}</button></nav><motion.nav :initial="reduced ? false : { opacity: 0, y: -4 }" :animate="{ opacity: 1, y: 0 }" :transition="{ duration: reduced ? 0 : 0.15 }" v-if="open" id="public-navigation" class="max-h-[70vh] overflow-y-auto border-t border-white/20 px-5 pb-5 xl:hidden" aria-label="Mobile navigation"><RouterLink v-for="link in links" :key="link.to" :to="link.to" class="block py-3 text-sm text-white">{{ link.label }}</RouterLink><RouterLink :to="user ? (loginDestination(undefined, user.role)) : '/login'" class="block py-3 font-semibold text-white">{{ user ? 'Dashboard' : 'Log in' }}</RouterLink><button v-if="user" class="py-3 text-sm text-white" :disabled="busy" @click="signOut">Log out</button><RouterLink to="/register" class="block py-3 text-sm text-white">Membership</RouterLink><RouterLink to="/membership/status" class="block py-3 text-sm text-white">Application status</RouterLink></motion.nav><p v-if="error" role="alert" class="mx-auto max-w-7xl px-5 pb-4 text-sm text-white">{{ error }}</p></header></template>
